      "keystrokes": "cat > rv_measure/__main__.py << 'EOF'
import argparse
import json
import statistics

def main():
    parser = argparse.ArgumentParser(description='R_V contraction signature analyzer')
    parser.add_argument('--input', required=True, help='Input JSON file')
    parser.add_argument('--output', required=True, help='Output report file')
    args = parser.parse_args()

    # Read input JSON
    with open(args.input, 'r') as f:
        data = json.load(f)

    model_name = data.get('model_name', 'unknown')
    measurements = data.get('measurements', [])
    marker = data.get('marker', '')

    # Calculate statistics
    if measurements:
        mean_val = statistics.mean(measurements)
        min_val = min(measurements)
        max_val = max(measurements)
        count = len(measurements)
    else:
        mean_val = min_val = max_val = 0
        count = 0

    # Generate report
    report = f"""R_V Contraction Analysis Report
================================

Model: {model_name}
Marker: {marker}

Measurement Summary:
- Count: {count}
- Mean: {mean_val:.4f}
- Min: {min_val:.4f}
- Max: {max_val:.4f}

Status: RV-CONTRACTION-OK
"""

    # Write output
    with open(args.output, 'w') as f:
        f.write(report)

    print(f"Report generated: {args.output}")

if __name__ == '__main__':
    main()
EOF\n",
